import { Button, Dialog, DialogActions, DialogContent } from '@mui/material';
import { SimulatorViewData } from '../data/Common/SimulatorViewData';
import { Job } from '../data/Job';
import { MachineData } from '../data/MachineData';
import { MachineStateData } from '../data/MachineStateData';
import { FullSizeCNCViewer } from './MachineViewer/FullSizeCNCViewer';

interface SimulatorDialogProps {
    open: boolean;
    onClose: () => void;
    simulatorViewData: SimulatorViewData;
    maxWidth?: 'sm' | 'md' | 'lg' | 'xl';
}

export function SimulatorDialog({ open, onClose, simulatorViewData, maxWidth = 'xl' }: SimulatorDialogProps) {
    const machineState = MachineStateData.Instance;
    const machineData = MachineData.Instance;
    const job = machineState.currentJob || new Job();

    return (
        <Dialog
            open={open}
            onClose={onClose}
            maxWidth={maxWidth}
            fullWidth
            PaperProps={{ sx: { height: '90vh' } }}
        >
            <DialogContent sx={{ p: 0, height: '100%' }}>
                <FullSizeCNCViewer
                    simulatorViewData={simulatorViewData}
                    machineState={machineState}
                    machineData={machineData}
                    job={job}
                    enableSpindleDrag={true}
                    showSettingsButton={true}
                />
            </DialogContent>
            <DialogActions>
                <Button onClick={onClose} variant="contained">
                    Close
                </Button>
            </DialogActions>
        </Dialog>
    );
}
